import{_ as n,C as r,o as c,c as h,j as e,a as d,E as a,a5 as l}from"./chunks/framework.CyyS6Zdm.js";const P=JSON.parse('{"title":"徽标","description":"","frontmatter":{},"headers":[],"relativePath":"components/badge.md","filePath":"components/badge.md","lastUpdated":1787291538000}'),s={name:"components/badge.md"},b={id:"徽标",tabindex:"-1"};function u(p,t,m,g,x,f){const i=r("Badge",!0),o=r("XhDemo");return c(),h("div",null,[e("h1",b,[t[0]||(t[0]=d("徽标 ",-1)),a(i,{type:"info",text:"badge"}),t[1]||(t[1]=d()),t[2]||(t[2]=e("a",{class:"header-anchor",href:"#徽标","aria-label":'Permalink to "徽标 <Badge type="info" text="badge" />"'},"​",-1))]),t[3]||(t[3]=l('<p>提醒你注意某个东西：它有几条未读、处在什么状态、是不是新的。 徽标说的是「有事情发生了」，不是「这是什么」——后者是<a href="./tag">标签</a>的活。</p><h2 id="何时使用" tabindex="-1">何时使用 <a class="header-anchor" href="#何时使用" aria-label="Permalink to &quot;何时使用&quot;">​</a></h2><ul><li>计数角标：未读消息、购物车件数、待办条数。</li><li>小红点：只表示「有新的」，不说有几条。</li><li>状态提示：在线 / 离线、进行中、新。</li><li>附着在按钮、头像、标签页、菜单项上，报告那个东西的状态。</li></ul><h2 id="何时不用" tabindex="-1">何时不用 <a class="header-anchor" href="#何时不用" aria-label="Permalink to &quot;何时不用&quot;">​</a></h2><ul><li>表达「这是什么」——分类、技能、筛选条件：用<a href="./tag">标签</a>，它承载实体身份，还能被摘掉。</li><li>用户要点它来筛选或删除：徽标不接交互，那是标签的语义。</li><li>表达进度：用<a href="./progress">进度条</a>。</li><li>是一个可开关的选项：用<a href="./toggle">切换按钮</a>。</li></ul><h2 id="特性" tabindex="-1">特性 <a class="header-anchor" href="#特性" aria-label="Permalink to &quot;特性&quot;">​</a></h2><ul><li>形态 · 语气 · 尺寸三轴与其余组件同源。</li><li><code>count</code> 自己出数字，超过 <code>max</code>（默认 99）写成「99+」。</li><li>计数为 0 时整枚收起，要显示 0 就开 <code>showZero</code>。</li><li><code>dot</code> 收成一个圆点：只表示「有」，不表示「有几个」。</li><li><code>label</code> 给读屏一整句：光念「3」听不出是什么的 3。</li></ul><h2 id="示例" tabindex="-1">示例 <a class="header-anchor" href="#示例" aria-label="Permalink to &quot;示例&quot;">​</a></h2><h3 id="变体" tabindex="-1">变体 <a class="header-anchor" href="#变体" aria-label="Permalink to &quot;变体&quot;">​</a></h3><p>badge 没有状态机，connect 直接由 props 算属性</p>',10)),a(o,{src:"badge/01-basic"}),t[4]||(t[4]=e("h3",{id:"用作状态标记",tabindex:"-1"},[d("用作状态标记 "),e("a",{class:"header-anchor",href:"#用作状态标记","aria-label":'Permalink to "用作状态标记"'},"​")],-1)),t[5]||(t[5]=e("p",null,"徽标不接收焦点、也不进 Tab 序列，状态语义靠文字本身表达",-1)),a(o,{src:"badge/02-status"}),t[6]||(t[6]=e("h3",{id:"形态",tabindex:"-1"},[d("形态 "),e("a",{class:"header-anchor",href:"#形态","aria-label":'Permalink to "形态"'},"​")],-1)),t[7]||(t[7]=e("p",null,"variant 决定颜色怎么用：实心填底、淡色填底、只描边",-1)),a(o,{src:"badge/03-variant"}),t[8]||(t[8]=e("h3",{id:"语气",tabindex:"-1"},[d("语气 "),e("a",{class:"header-anchor",href:"#语气","aria-label":'Permalink to "语气"'},"​")],-1)),t[9]||(t[9]=e("p",null,"tone 决定用哪族颜色，与 variant 正交；这里固定 solid 形态只看语气的差别",-1)),a(o,{src:"badge/04-tone"}),t[10]||(t[10]=e("h3",{id:"尺寸",tabindex:"-1"},[d("尺寸 "),e("a",{class:"header-anchor",href:"#尺寸","aria-label":'Permalink to "尺寸"'},"​")],-1)),t[11]||(t[11]=e("p",null,"size 只改内边距与字号，不写就是缺省档",-1)),a(o,{src:"badge/05-size"}),t[12]||(t[12]=e("h3",{id:"带图元的标签",tabindex:"-1"},[d("带图元的标签 "),e("a",{class:"header-anchor",href:"#带图元的标签","aria-label":'Permalink to "带图元的标签"'},"​")],-1)),t[13]||(t[13]=e("p",null,"根是 inline-flex 且自带间距，图标或头像直接写进内容里跟文字并排",-1)),a(o,{src:"badge/06-with-glyph"}),t[14]||(t[14]=e("h3",{id:"自定义配色",tabindex:"-1"},[d("自定义配色 "),e("a",{class:"header-anchor",href:"#自定义配色","aria-label":'Permalink to "自定义配色"'},"​")],-1)),t[15]||(t[15]=e("p",null,"不写 variant 时底色与文字色取自组件令牌；描边这一条直接写 border-color",-1)),a(o,{src:"badge/07-custom-color"}),t[16]||(t[16]=e("h3",{id:"挂成角标",tabindex:"-1"},[d("挂成角标 "),e("a",{class:"header-anchor",href:"#挂成角标","aria-label":'Permalink to "挂成角标"'},"​")],-1)),t[17]||(t[17]=e("p",null,"外层套一层定位上下文，徽标就落到子元素的角上。计数、上限截断、0 值收起、圆点都归徽标自己算，宿主只管定位",-1)),a(o,{src:"badge/08-anchor"}),t[18]||(t[18]=l('<h2 id="产物" tabindex="-1">产物 <a class="header-anchor" href="#产物" aria-label="Permalink to &quot;产物&quot;">​</a></h2><table tabindex="0"><thead><tr><th>层</th><th>值</th></tr></thead><tbody><tr><td>自定义元素</td><td><code>&lt;xh-badge&gt;</code></td></tr><tr><td>Vue 组件</td><td><code>XhBadge</code></td></tr><tr><td>状态机</td><td>无，<code>connect</code> 直接由 props 算属性</td></tr><tr><td>皮肤</td><td><code>@xihan-ui/styles/badge.css</code></td></tr></tbody></table><h2 id="解剖" tabindex="-1">解剖 <a class="header-anchor" href="#解剖" aria-label="Permalink to &quot;解剖&quot;">​</a></h2><p>部件名即 <code>data-part</code> 属性值，也是皮肤的选择器。加粗的是必备部件，不渲染它组件不工作（Web Components 适配器会在诊断通道上报 <code>wc.missing-part</code>）。</p><p><code>data-scope=&quot;badge&quot;</code>：<strong><code>root</code></strong></p><h2 id="props" tabindex="-1">Props <a class="header-anchor" href="#props" aria-label="Permalink to &quot;Props&quot;">​</a></h2><table tabindex="0"><thead><tr><th>属性</th><th>类型</th><th>必填</th><th>说明</th></tr></thead><tbody><tr><td><code>count</code></td><td><code>number</code></td><td></td><td>计数。给了它徽标就自己出数字，超过 max 写成「max+」。 与默认插槽二选一：插槽有内容时以插槽为准。</td></tr><tr><td><code>dot</code></td><td><code>boolean</code></td><td></td><td>只出一个点，不出数字。给了它 count 只用来决定显不显示。</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td></td><td>读屏怎么念这枚徽标。 角标挂在按钮、头像上时，光念数字听不出这是什么，得由宿主给出「3 条未读」这样的整句。</td></tr><tr><td><code>max</code></td><td><code>number</code></td><td></td><td>计数上限，默认 99：再多也只写 99+，免得徽标被撑变形。</td></tr><tr><td><code>showZero</code></td><td><code>boolean</code></td><td></td><td>计数为 0 时是否照样显示，默认不显示——没有未读就不该有角标。</td></tr><tr><td><code>size</code></td><td><code>Size</code></td><td></td><td>尺寸：sm / md / lg</td></tr><tr><td><code>tone</code></td><td><code>Tone</code></td><td></td><td>语气：brand / neutral / success / warning / danger / info，决定用哪族颜色</td></tr><tr><td><code>variant</code></td><td><code>BadgeVariant</code></td><td></td><td></td></tr></tbody></table><h2 id="connect-api" tabindex="-1">connect API <a class="header-anchor" href="#connect-api" aria-label="Permalink to &quot;connect API&quot;">​</a></h2><p><code>connect</code> 产出的对象。<code>getXxxProps()</code> 铺到对应部件的宿主元素上，其余是可读状态与操作入口。</p><table tabindex="0"><thead><tr><th>成员</th><th>类型</th><th>说明</th></tr></thead><tbody><tr><td><code>visible</code></td><td><code>boolean</code></td><td>此刻该不该渲染：计数为 0 且没开 showZero 时为假。</td></tr><tr><td><code>text</code></td><td><code>string</code></td><td>算好的显示文本：超过 max 的写成「99+」；dot 模式与无 count 时为空串。</td></tr><tr><td><code>getRootProps</code></td><td><code>() =&gt; T[&#39;element&#39;]</code></td><td></td></tr></tbody></table><h2 id="键盘" tabindex="-1">键盘 <a class="header-anchor" href="#键盘" aria-label="Permalink to &quot;键盘&quot;">​</a></h2><p>规格出处：<a href="https://www.w3.org/WAI/ARIA/apg/" target="_blank" rel="noreferrer">W3C APG</a></p><p>无键盘交互（不接收焦点，或焦点行为完全由原生元素提供）。</p><h2 id="无障碍" tabindex="-1">无障碍 <a class="header-anchor" href="#无障碍" aria-label="Permalink to &quot;无障碍&quot;">​</a></h2><p>下面这些由 <code>connect</code> 铺到部件上，作者不必自己写；重复写反而会覆盖掉正确值。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>aria-label</code></td><td>props.label</td></tr><tr><td><code>root</code></td><td><code>role</code></td><td>&#39;status&#39; | undefined</td></tr></tbody></table><h2 id="样式" tabindex="-1">样式 <a class="header-anchor" href="#样式" aria-label="Permalink to &quot;样式&quot;">​</a></h2><p>默认皮肤 <code>@xihan-ui/styles/badge.css</code> 按部件选择：<code>[data-scope=&quot;badge&quot;][data-part=&quot;root&quot;]</code>。它落在 <code>xihan.components</code> 层；业务样式不写进 <code>@layer</code> 即高于全部库层，要按层压过来就写进 <code>xihan.overrides</code>。</p><h2 id="数据属性" tabindex="-1">数据属性 <a class="header-anchor" href="#数据属性" aria-label="Permalink to &quot;数据属性&quot;">​</a></h2><p>由 <code>connect</code> 产出并铺到部件上，皮肤与测试都据此选择；<code>data-disabled</code> 这类无值属性在条件不成立时整个不出现。</p><table tabindex="0"><thead><tr><th>部件</th><th>属性</th><th>值</th></tr></thead><tbody><tr><td><code>root</code></td><td><code>data-dot</code></td><td>&#39;&#39;（条件成立时才出现）</td></tr><tr><td><code>root</code></td><td><code>data-size</code></td><td>props.size</td></tr><tr><td><code>root</code></td><td><code>data-tone</code></td><td>props.tone</td></tr><tr><td><code>root</code></td><td><code>data-variant</code></td><td>props.variant</td></tr></tbody></table><h2 id="css-变量" tabindex="-1">CSS 变量 <a class="header-anchor" href="#css-变量" aria-label="Permalink to &quot;CSS 变量&quot;">​</a></h2><p>本组件皮肤读的组件级令牌，写在组件自身或任意祖先上都生效。缺省值来自<a href="./../guide/theme">设计令牌</a>，不设即按缺省走。</p><p><code>--xh-badge-bg</code> · <code>--xh-badge-dot-size</code> · <code>--xh-badge-fg</code> · <code>--xh-badge-font-size</code> · <code>--xh-badge-font-weight</code></p><h2 id="rtl" tabindex="-1">RTL <a class="header-anchor" href="#rtl" aria-label="Permalink to &quot;RTL&quot;">​</a></h2><p>皮肤用逻辑属性排布（<code>inline-start</code> 一族），<code>dir=&quot;rtl&quot;</code> 下自动镜像。</p><h2 id="组合" tabindex="-1">组合 <a class="header-anchor" href="#组合" aria-label="Permalink to &quot;组合&quot;">​</a></h2><ul><li>挂在<a href="./avatar">头像</a>、<a href="./button">按钮</a>、<a href="./tabs">标签页</a>的标签上做角标： 外层套一层定位上下文，徽标就落到子元素的角上。</li></ul><h2 id="最佳实践" tabindex="-1">最佳实践 <a class="header-anchor" href="#最佳实践" aria-label="Permalink to &quot;最佳实践&quot;">​</a></h2><ul><li>角标要给 <code>label</code>：读屏念到孤零零一个数字，用户不知道那是未读数还是别的。</li><li>状态别只用颜色区分：红绿色觉障碍的用户看不出差别，文字必须说清楚。</li><li>计数会变的地方交给 <code>count</code> 算，别自己拼「99+」——上限口径散在各处迟早不一致。</li></ul><h2 id="反模式" tabindex="-1">反模式 <a class="header-anchor" href="#反模式" aria-label="Permalink to &quot;反模式&quot;">​</a></h2><ul><li>拿徽标当分类标签用：它不可交互、摘不掉，用户点了没反应。</li><li>一屏里到处都是高饱和度的徽标：全都在喊，等于都没喊。</li><li>用徽标承载长句子。</li></ul>',32))])}const k=n(s,[["render",u]]);export{P as __pageData,k as default};
